### Step 3: Implement `sscc()` in `planets.rs`

Builds sin(k×L) and cos(k×L) for k=1..n using double-angle recurrence (c-ref-moshier.md lines 201–215):

```rust
fn sscc(
    k: usize,
    arg: f64,
    n: i8,
    ss: &mut [[f64; 24]; 9],
    cc: &mut [[f64; 24]; 9],
) {
    let n = n as usize;
    let su = arg.sin();
    let cu = arg.cos();
    ss[k][0] = su;
    cc[k][0] = cu;
    let mut sv = 2.0 * su * cu;
    let mut cv = cu * cu - su * su;
    ss[k][1] = sv;
    cc[k][1] = cv;
    for i in 2..n {
        let s = su * cv + cu * sv;
        cv = cu * cv - su * sv;
        sv = s;
        ss[k][i] = sv;
        cc[k][i] = cv;
    }
}
```

### Step 4: Implement `moshplan2()` in `planets.rs`

The core series evaluator (c-ref-moshier.md lines 217–263). This is the most complex step.

```rust
pub fn moshplan2(jd: f64, table: &PlantTbl) -> [f64; 3] {
    let t = (jd - J2000) / TIMESCALE;

    // Step 1: build sin/cos lookup tables
    let mut ss = [[0.0f64; 24]; 9];
    let mut cc = [[0.0f64; 24]; 9];
    for i in 0..9 {
        if table.max_harmonic[i] > 0 {
            let sr = (mods3600(FREQS[i] * t) + PHASES[i]) * STR;
            sscc(i, sr, table.max_harmonic[i], &mut ss, &mut cc);
        }
    }

    // Step 2: walk arg_tbl, consuming from lon/lat/rad in parallel
    let arg = table.arg_tbl;
    let mut pl = 0usize; // cursor into lon_tbl
    let mut pb = 0usize; // cursor into lat_tbl
    let mut pr = 0usize; // cursor into rad_tbl
    let mut p = 0usize;  // cursor into arg_tbl
    let mut sl = 0.0f64;
    let mut sb = 0.0f64;
    let mut sr = 0.0f64;

    loop {
        let np = arg[p];
        p += 1;
        if np < 0 { break; }

        if np == 0 {
            // Polynomial term
            let nt = arg[p] as usize;
            p += 1;
            // Horner evaluation: cu = c[0]*T^nt + c[1]*T^(nt-1) + ... + c[nt]
            let mut cu = table.lon_tbl[pl]; pl += 1;
            for _ in 0..nt { cu = cu * t + table.lon_tbl[pl]; pl += 1; }
            sl += mods3600(cu);

            let mut cu = table.lat_tbl[pb]; pb += 1;
            for _ in 0..nt { cu = cu * t + table.lat_tbl[pb]; pb += 1; }
            sb += cu;

            let mut cu = table.rad_tbl[pr]; pr += 1;
            for _ in 0..nt { cu = cu * t + table.rad_tbl[pr]; pr += 1; }
            sr += cu;
            continue;
        }

        // Periodic term: combine np argument pairs
        let np = np as usize;
        let mut sv = 0.0f64;
        let mut cv = 0.0f64;
        let mut k1 = false;
        for _ in 0..np {
            let j = arg[p] as i32; p += 1;
            let m = arg[p] as usize; p += 1;
            if j == 0 { continue; }
            let k = (j.unsigned_abs() - 1) as usize;
            let su = if j < 0 { -ss[m - 1][k] } else { ss[m - 1][k] };
            let cu = cc[m - 1][k];
            if !k1 {
                sv = su; cv = cu; k1 = true;
            } else {
                let tmp = su * cv + cu * sv;
                cv = cu * cv - su * sv;
                sv = tmp;
            }
        }

        let nt = arg[p] as usize;
        p += 1;

        // Horner in two streams (cos/sin amplitude pairs)
        let mut cu = table.lon_tbl[pl]; pl += 1;
        let mut su = table.lon_tbl[pl]; pl += 1;
        for _ in 0..nt {
            cu = cu * t + table.lon_tbl[pl]; pl += 1;
            su = su * t + table.lon_tbl[pl]; pl += 1;
        }
        sl += cu * cv + su * sv;

        let mut cu = table.lat_tbl[pb]; pb += 1;
        let mut su = table.lat_tbl[pb]; pb += 1;
        for _ in 0..nt {
            cu = cu * t + table.lat_tbl[pb]; pb += 1;
            su = su * t + table.lat_tbl[pb]; pb += 1;
        }
        sb += cu * cv + su * sv;

        let mut cu = table.rad_tbl[pr]; pr += 1;
        let mut su = table.rad_tbl[pr]; pr += 1;
        for _ in 0..nt {
            cu = cu * t + table.rad_tbl[pr]; pr += 1;
            su = su * t + table.rad_tbl[pr]; pr += 1;
        }
        sr += cu * cv + su * sv;
    }

    // Step 3: convert to final units
    [
        STR * sl,                                        // longitude in radians
        STR * sb,                                        // latitude in radians
        STR * table.distance * sr + table.distance,      // radius in AU
    ]
}
```

