### Step 6: Write C golden data generator

`tests/c-gen/gen_moshier_planet.c` — calls `swi_moshplan2()` for all 9 planets at 9 test epochs spanning the Moshier range:

```c
#include <stdio.h>
#include <math.h>
#include "swephexp.h"
#include "swephlib.h"
#include "sweph.h"

// Test epochs: J2000 ± {0, 100, 500, 1000, 3000} years
// All within MOSHPLEPH_START..MOSHPLEPH_END
static double epochs[] = {
    2451545.0 - 3000.0 * 365.25,  // ~-1000 BC
    2451545.0 - 1000.0 * 365.25,  // ~1000 AD
    2451545.0 - 500.0 * 365.25,
    2451545.0 - 100.0 * 365.25,
    2451545.0,                     // J2000
    2451545.0 + 100.0 * 365.25,
    2451545.0 + 500.0 * 365.25,
    2451545.0 + 1000.0 * 365.25,  // ~3000 AD
    2451545.0 + 999.0 * 365.25,   // near end of range
};
#define NEPOCHS 9

static const char *planet_names[] = {
    "mercury","venus","earth","mars","jupiter",
    "saturn","uranus","neptune","pluto"
};
#define NPLANETS 9

int main(void) {
    printf("{\\n");
    for (int ip = 0; ip < NPLANETS; ip++) {
        printf("  \"%s\": [\\n", planet_names[ip]);
        for (int ie = 0; ie < NEPOCHS; ie++) {
            double pobj[3];
            swi_moshplan2(epochs[ie], ip, pobj);
            printf("    {\"jd\": %.20e, \"lon\": %.20e, \"lat\": %.20e, \"dist\": %.20e}",
                   epochs[ie], pobj[0], pobj[1], pobj[2]);
            if (ie < NEPOCHS - 1) printf(",");
            printf("\\n");
        }
        printf("  ]");
        if (ip < NPLANETS - 1) printf(",");
        printf("\\n");
    }
    printf("}\\n");
    return 0;
}
```

